//! 🧪️ The actual shared turn executes original paid queue owners without changing any grant.
use super::*;
use crate::{observe_retirement_allocations,ArtifactOwnedValueRetirementFactory,ErasedSnapshotRetirement,FactoryOwnedRetirement,retirement::{queue::RetirementQueue,OwnedValueRetirementFactory,RetirementCursor,shared::arc_bytes}};
use std::sync::Arc;
fn demands(queue:&RetirementQueue,body:usize)->RetirementDemand{RetirementDemand{copy_bytes:queue.next_copy_byte_demand().unwrap(),capacity_bytes:queue.next_capacity_byte_demand(body).unwrap(),release_bytes:queue.next_release_byte_demand().unwrap(),depth:queue.next_depth_demand().unwrap()}}
#[test]
fn retirement_turn_original_queue_preserves_full_grants_all_physical_currencies_and_paused_custody(){
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for empty in [false,true]{for body in law["copyBudgets"].as_array().unwrap(){for cut in law["cancellationCuts"].as_array().unwrap(){
  let capacity=law[if empty{"emptyCapacity"}else{"originalCapacity"}].as_u64().unwrap()as usize;let mut text=String::with_capacity(capacity);if !empty{text.push_str(&law["text"].as_str().unwrap().repeat(law["repeat"].as_u64().unwrap()as usize));}let mut original=Some(text);let factory:Arc<dyn ArtifactOwnedValueRetirementFactory<String>>=Arc::new(OwnedValueRetirementFactory::<String>::default());let held=capacity+arc_bytes::<OwnedValueRetirementFactory<String>>();let mut queue=RetirementQueue::default();let mut births=0;let mut releases=0;
  let reserve=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:queue.next_reserve_capacity_byte_demand().unwrap(),maximum_depth:1,..Default::default()};let(p,heap)=observe_retirement_allocations(||queue.reserve_step(reserve).unwrap());assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);births+=heap.0;releases+=heap.1;
  let grant=RetainedCloneGrant{maximum_items:1,maximum_capacity_bytes:FactoryOwnedRetirement::<String>::constructor_capacity_bytes(),maximum_depth:1,..Default::default()};let((owner,p),heap)=observe_retirement_allocations(||FactoryOwnedRetirement::admit_original(&mut original,&factory,grant).unwrap().unwrap());assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);births+=heap.0;releases+=heap.1;let(p,heap)=observe_retirement_allocations(||match queue.admit_retirement(owner as Box<dyn ErasedSnapshotRetirement>,RetainedCloneGrant{maximum_items:1,maximum_depth:1,..Default::default()}){Ok(progress)=>progress,Err((error,_original))=>panic!("admitted original queue refused: {}",error.message)});assert_eq!(p.retained_capacity_bytes,0);assert_eq!(heap,(0,0));let(_,heap)=observe_retirement_allocations(||drop(factory));assert_eq!(heap,(0,0));
  for turn in 0..1000000{
   let body=body.as_u64().unwrap()as usize;let(demand,heap)=observe_retirement_allocations(||demands(&queue,body));assert_eq!(heap,(0,0));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:body.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
   for under in [Some(RetainedCloneGrant{maximum_items:0,..grant}),(demand.copy_bytes>0).then_some(RetainedCloneGrant{maximum_copy_bytes:demand.copy_bytes.saturating_sub(1),..grant}),(demand.capacity_bytes>0).then_some(RetainedCloneGrant{maximum_capacity_bytes:demand.capacity_bytes.saturating_sub(1),..grant}),(demand.release_bytes>0).then_some(RetainedCloneGrant{maximum_release_bytes:demand.release_bytes.saturating_sub(1),..grant}),(demand.depth>0).then_some(RetainedCloneGrant{maximum_depth:demand.depth.saturating_sub(1),..grant})].into_iter().flatten(){let mut calls=0;let(step,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,under,|_|->Result<(RetainedCloneStep,bool),ValueError>{calls+=1;unreachable!("undergrant touched original owner")}).unwrap());assert_eq!(calls,0);assert_eq!(step.progress(),Default::default());assert_eq!(heap,(0,0));}
   let(step,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,grant,|actual|{assert_eq!(actual,grant);let step=queue.step(actual)?;Ok((step,queue.terminal_is_empty()))}).unwrap());let p=step.progress();assert!(p.fits(grant));assert_eq!((p.retained_capacity_bytes,p.released_bytes),heap);births+=heap.0;releases+=heap.1;if queue.terminal_is_empty(){break;}assert!(turn<999999,"original queue stalled");if turn==cut.as_u64().unwrap()as usize{let(same,heap)=observe_retirement_allocations(||queue);queue=same;assert_eq!(heap,(0,0));}
  }
  assert!(queue.terminal_is_empty());assert_eq!(releases,held+births);let(_,heap)=observe_retirement_allocations(||drop((queue,original)));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual retirement turn empty={empty} originalCapacity={capacity} body={body} paused={cut} births={births} physical={releases} originalGrantForwarded=true terminalDrop=0");
 }}}
}
#[test]
fn retirement_turn_rejects_false_completion_and_each_overspent_currency_without_changing_custody(){
 let original=String::with_capacity(8192);let pointer=original.as_ptr();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:23,maximum_capacity_bytes:31,maximum_release_bytes:47,maximum_depth:7};let demand=RetirementDemand{copy_bytes:23,capacity_bytes:31,release_bytes:47,depth:7};
 for progress in [RetainedCloneProgress{copied_items:2,..Default::default()},RetainedCloneProgress{copied_bytes:24,..Default::default()},RetainedCloneProgress{retained_capacity_bytes:32,..Default::default()},RetainedCloneProgress{released_bytes:48,..Default::default()}]{let(result,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,grant,|actual|->Result<(RetainedCloneStep,bool),ValueError>{assert_eq!(actual,grant);Ok((RetainedCloneStep::Progress(progress),false))}));assert!(matches!(result,Err(RetirementTurnError::Receipt(error))if error.kind==ValueRefusalKind::InvariantViolated));assert_eq!(heap,(0,0));assert_eq!(original.as_ptr(),pointer);}
 let(result,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,grant,|_|->Result<(RetainedCloneStep,bool),ValueError>{Ok((RetainedCloneStep::Complete(Default::default()),false))}));assert!(matches!(result,Err(RetirementTurnError::Receipt(error))if error.kind==ValueRefusalKind::InvariantViolated));assert_eq!(heap,(0,0));assert_eq!(original.as_ptr(),pointer);
 let(result,heap)=observe_retirement_allocations(||advance_retirement_turn(demand,grant,|_|->Result<(RetainedCloneStep,bool),ValueError>{Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"actual original issuer refusal"))}));assert!(matches!(result,Err(RetirementTurnError::Owner(error))if error.message=="actual original issuer refusal"));assert_eq!(heap,(0,0));assert_eq!(original.as_ptr(),pointer);let mut owner=crate::retirement::controlled::ControlledRetirement::new(original).unwrap();for _ in 0..1000000{let demand=RetirementDemand{copy_bytes:owner.next_work_byte_demand().unwrap(),capacity_bytes:owner.next_birth_bytes(23).unwrap_or(0),release_bytes:owner.next_close_byte_demand().unwrap(),depth:owner.next_depth_demand().unwrap()};let actual=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:23.max(demand.copy_bytes),maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};owner.close_step(actual);if owner.terminal_is_empty(){break;}}assert!(owner.terminal_is_empty());eprintln!("[DEBUG] actual retirement turn rejects4 overspent currencies/false whole-parent completion; exact original refusal preserved0heap");
}
